// Synthetic local public descriptor consumer; not an AGS MCP server.
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const json = relative => JSON.parse(readFileSync(path.join(root, relative), "utf8"));
export const WORKFLOW_STATES = Object.freeze(["DRAFT", "CONFIRMED", "CANCELLED"]);
export function listTools() {
  const choices = json("business/booking-windows.json").items.map(item => item.value);
  return [{name:"reserve_visit",description:"방문 예약을 생성한다.",inputSchema:{type:"object",
    properties:{bookingWindow:{type:"string",enum:choices,description:"예약 구분"}},
    required:["bookingWindow"],additionalProperties:false},
    outputSchema:{type:"object",properties:{status:{type:"string",enum:[...WORKFLOW_STATES]}}}}];
}
export function renderToolHelp(name) {
  const descriptor = listTools().find(tool => tool.name === name);
  if (!descriptor) throw new Error("UNKNOWN_TOOL");
  return [descriptor.name, descriptor.description, ...Object.entries(descriptor.inputSchema.properties)
    .map(([key, property]) => key + ": " + property.description + " [" + property.enum.join(", ") + "]")].join("\n");
}
export function invokeTool(name, input) {
  const descriptor = listTools().find(tool => tool.name === name);
  if (!descriptor) throw new Error("UNKNOWN_TOOL");
  if (!input || Object.keys(input).length !== 1 || !descriptor.inputSchema.properties.bookingWindow.enum.includes(input.bookingWindow))
    throw new Error("INVALID_BOOKING_WINDOW");
  return {fixture:true,bookingWindow:input.bookingWindow,status:WORKFLOW_STATES[0]};
}
export function diagnoseRuntime() {
  return {application:"synthetic-booking-tool-fixture",version:"0.0.0",nodeVersion:process.version,nodeExecPath:process.execPath};
}
if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const [command, name, argument, ...extra] = process.argv.slice(2);
  try {
    if (extra.length) throw new Error("INVALID_REQUEST");
    if (command === "list-tools" && !name) console.log(JSON.stringify({tools:listTools()}));
    else if (command === "help" && name && !argument) console.log(renderToolHelp(name));
    else if (command === "diagnose" && !name) console.log(JSON.stringify(diagnoseRuntime()));
    else if (command === "invoke" && name && argument) console.log(JSON.stringify(invokeTool(name,JSON.parse(argument))));
    else throw new Error("INVALID_REQUEST");
  } catch (cause) {
    const known = ["INVALID_REQUEST","UNKNOWN_TOOL","INVALID_BOOKING_WINDOW"];
    console.error(JSON.stringify({error:known.includes(cause?.message) ? cause.message : "FIXTURE_READ_OR_JSON_ERROR"}));
    process.exitCode = 2;
  }
}

