// Existing public-boundary characterization. Keep these assertions when adding regressions.
import test from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
const app = fileURLToPath(new URL("../app/tool-catalog.mjs",import.meta.url));
const call = args => spawnSync(process.execPath,[app,...args],{encoding:"utf8"});
const ok = args => { const result = call(args); assert.equal(result.status,0,result.stderr); return result.stdout; };
test("public descriptor preserves fixed workflow-state contract",()=>{
  const tool = JSON.parse(ok(["list-tools"])).tools.find(item=>item.name==="reserve_visit");
  assert.deepEqual(tool.inputSchema.required,["bookingWindow"]);
  assert.equal(tool.inputSchema.additionalProperties,false);
  assert.deepEqual(tool.outputSchema.properties.status.enum,["DRAFT","CONFIRMED","CANCELLED"]);
});
test("public invocation accepts known value and rejects an unknown value",()=>{
  assert.deepEqual(JSON.parse(ok(["invoke","reserve_visit",'{"bookingWindow":"AM"}'])),
    {fixture:true,bookingWindow:"AM",status:"DRAFT"});
  const rejected = call(["invoke","reserve_visit",'{"bookingWindow":"NIGHT"}']);
  assert.equal(rejected.status,2);
  assert.deepEqual(JSON.parse(rejected.stderr),{error:"INVALID_BOOKING_WINDOW"});
});
test("help reads the registered descriptor",()=>{
  const help = ok(["help","reserve_visit"]);
  assert.match(help,/reserve_visit/);
  assert.match(help,/bookingWindow/);
  assert.match(help,/AM/);
  assert.match(help,/PM/);
});
